class Solution:

	def solve(self, k, n, curr):
		if k == n:
			num = 0
			for i in range(len(curr)):
				num = num * 2 + int(curr[i])
			if num != 0:
				self.ans.append(num)
			return
		curr.append('0')
		self.solve(k + 1, n, curr)
		curr.pop()
		if len(curr) == 0 or curr[-1] == '0':
			curr.append('1')
			self.solve(k + 1, n, curr)
			curr.pop()

	def numberWithNoConsecutiveOnes(self, n):
		self.ans = []
		self.solve(0, n, [])
		return self.ans
